import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  useSearch,
  createMemoryHistory,
} from '@tanstack/react-router';
import { z } from 'zod';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

const SearchSchema = z.object({
  page: z.number().int().min(1).default(1),
  q: z.string().default(''),
});

export function SearchView() {
  const { page, q } = useSearch({ from: searchRoute.id });
  return (
    <>
      <p>page: {page}</p>
      <p>q: {q}</p>
    </>
  );
}

export const searchRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/search',
  validateSearch: (raw: Record<string, unknown>) => SearchSchema.parse(raw),
  component: SearchView,
});

const routeTree = rootRoute.addChildren([searchRoute]);

export function makeRouter(initialEntries: string[] = ['/search']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
